import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'ok'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'test'});

describe('ChatOrchestrator beforeSession', () => {
  it('invokes onError and afterSession when beforeSession throws', async () => {
    // specs/hal-engine-config-hooks/spec.md#0
    const error = new Error('beforeSession failed');
    const calls: string[] = [];

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          calls.push('beforeSession');
          throw error;
        },
        onError: async () => {
          calls.push('onError');
        },
        afterSession: async () => {
          calls.push('afterSession');
        }
      }
    });

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('beforeSession failed');

    expect(calls).toEqual(['beforeSession', 'onError', 'afterSession']);
  });
});

